<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import type { UploadFile } from 'element-plus'
import { UploadFilled, View, Cpu, Download, ArrowLeft, Lock } from '@element-plus/icons-vue'
import { http, request, type ArchiveDocument, type ArchiveVersion, type Employee, type EmployeeStatusHistory, type Page, type OcrResult } from '../api/http'
import { useAuthStore } from '../stores/auth'

const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const employeeId = Number(route.params.id)
const loading = ref(false); const employee = ref<Employee | null>(null); const documents = ref<Page<ArchiveDocument>>({ items: [], total: 0, page: 1, pageSize: 20 }); const history = ref<Page<EmployeeStatusHistory>>({ items: [], total: 0, page: 1, pageSize: 20 }); const versions = ref<Record<number, ArchiveVersion[]>>({}); const ocrAvailableIds = ref<number[]>([]); const uploading = ref(false)
const documentTypes = [{ label: '员工档案', value: 'employee_profile' }, { label: '入职材料', value: 'onboarding' }, { label: '调动材料', value: 'transfer' }, { label: '离职材料', value: 'offboarding' }]
const selectedType = ref('employee_profile')
const canManage = auth.roles.includes('HR_ADMIN')
async function load() { loading.value = true; try { const historyRequest = Promise.resolve(request<Page<EmployeeStatusHistory>>({ url: `/employees/${employeeId}/status-history`, params: { page: 1, pageSize: 20 } })).then((value) => value || ({ items: [], total: 0, page: 1, pageSize: 20 })).catch(() => ({ items: [], total: 0, page: 1, pageSize: 20 })); const [employeeData, documentsData, historyData] = await Promise.all([request<Employee>({ url: `/employees/${employeeId}` }), request<Page<ArchiveDocument>>({ url: `/archive/employees/${employeeId}/documents` }), historyRequest]); employee.value = employeeData; documents.value = documentsData; history.value = historyData; await Promise.all(documents.value.items.map(async (doc) => { const page = await request<Page<ArchiveVersion>>({ url: `/archive/documents/${doc.id}/versions`, params: { page: 1, pageSize: 20 } }); versions.value[doc.id] = page.items })); if (!canManage) { const currentVersions = Object.values(versions.value).flat().filter((version) => version.isCurrent); const available = await Promise.all(currentVersions.map(async (version) => { try { await request<OcrResult>({ url: `/archive/versions/${version.id}/ocr-result` }); return version.id } catch { return null } })); ocrAvailableIds.value = available.filter((id): id is number => id !== null) } } catch (e) { ElMessage.error(e instanceof Error ? e.message : '档案加载失败') } finally { loading.value = false } }
async function upload(file: File) { if (!['image/png', 'image/jpeg'].includes(file.type)) { ElMessage.warning('仅支持 PNG 或 JPEG 图片'); return } const form = new FormData(); form.append('documentType', selectedType.value); form.append('file', file); uploading.value = true; try { await request<ArchiveVersion>({ url: `/archive/employees/${employeeId}/documents`, method: 'POST', data: form, headers: { 'Content-Type': 'multipart/form-data' } }); ElMessage.success('材料已上传'); await load() } catch (e) { ElMessage.error(e instanceof Error ? e.message : '上传失败') } finally { uploading.value = false } }
async function triggerOcr(version: ArchiveVersion) { try { const result = await request<OcrResult>({ url: `/archive/versions/${version.id}/ocr`, method: 'POST' }); router.push({ path: `/ocr/${result.versionId}`, query: { employeeId: String(employeeId) } }) } catch (e) { ElMessage.error(e instanceof Error ? e.message : 'OCR 触发失败') } }
async function download(version: ArchiveVersion) { try { const response = await http.get(`/archive/versions/${version.id}/download`, { responseType: 'blob' }); const url = URL.createObjectURL(response.data); const anchor = document.createElement('a'); anchor.href = url; anchor.download = version.originalName; anchor.click(); URL.revokeObjectURL(url) } catch (e) { ElMessage.error(e instanceof Error ? e.message : '原图下载失败') } }
function requestAccess(version: ArchiveVersion) { router.push({ path: '/archive-access', query: { employeeId: String(employeeId), versionId: String(version.id) } }) }
function canMaintainVersion(version: ArchiveVersion) { return canManage && version.createdBy === auth.user?.id }
const statusLabel: Record<string, string> = { PENDING_ONBOARD: '待入职', ACTIVE: '在职', ON_LEAVE: '休假', INACTIVE: '离职' }
function statusText(status?: string) { return statusLabel[status || ''] || status || '未记录' }
const leaveDateRange = computed(() => employee.value?.status === 'ON_LEAVE' ? `${employee.value?.leaveStartDate || '?'} 至 ${employee.value?.leaveEndDate || '?'}` : '')
function departmentText(name?: string, id?: number) { return name || (id ? `部门 ${id}` : '未记录') }
function positionText(name?: string, id?: number) { return name || (id ? `岗位 ${id}` : '未记录') }
async function loadHistory(page = 1) { try { history.value = await request<Page<EmployeeStatusHistory>>({ url: `/employees/${employeeId}/status-history`, params: { page, pageSize: history.value.pageSize } }) } catch (e) { ElMessage.error(e instanceof Error ? e.message : '变更历史加载失败') } }
onMounted(load)
</script>

<template>
  <div class="page-head compact-head"><div><el-button text @click="router.push('/employees')"><el-icon><ArrowLeft /></el-icon>返回员工</el-button><span class="section-kicker">ARCHIVE / EVIDENCE</span><h1>{{ employee?.name || '员工档案' }}<el-tag v-if="employee?.status === 'ON_LEAVE'" type="primary" effect="plain" class="leave-tag">请假中</el-tag></h1><p>{{ employee?.employeeNo }} · 员工主数据与材料版本<template v-if="leaveDateRange"> · 请假 {{ leaveDateRange }}</template></p></div><div v-if="canManage" class="head-actions"><el-select v-model="selectedType" class="doc-type"><el-option v-for="item in documentTypes" :key="item.value" v-bind="item" /></el-select><el-upload :show-file-list="false" :auto-upload="false" accept="image/png,image/jpeg" :on-change="(uploadFile: UploadFile) => upload(uploadFile.raw!)"><el-button type="primary" class="action-button" :loading="uploading"><el-icon><UploadFilled /></el-icon>上传材料</el-button></el-upload></div></div>
  <el-alert type="info" :closable="false" show-icon class="inline-alert" title="原图、版本号与 SHA-256 指纹会被保留；OCR 只生成可复核的业务字段，不覆盖原始证据。" />
  <section class="surface-panel history-panel" v-loading="loading"><div class="panel-heading"><div><span class="section-kicker">CHANGE LOG</span><h2>状态与组织变更</h2></div><span class="panel-meta">共 {{ history.total }} 条</span></div><el-empty v-if="!history.items.length && !loading" description="暂无状态或组织变更记录" :image-size="56" /><el-table v-else :data="history.items" row-key="id" class="data-table history-table"><el-table-column label="时间" width="176"><template #default="scope">{{ new Date(scope.row.createdAt).toLocaleString('zh-CN') }}</template></el-table-column><el-table-column label="变更前" min-width="230"><template #default="scope"><div class="history-value"><strong>{{ statusText(scope.row.beforeStatus) }}</strong><small>{{ departmentText(scope.row.beforeDepartmentName, scope.row.beforeDepartmentId) }} · {{ positionText(scope.row.beforePositionName, scope.row.beforePositionId) }}</small></div></template></el-table-column><el-table-column label="变更后" min-width="230"><template #default="scope"><div class="history-value"><strong>{{ statusText(scope.row.afterStatus) }}</strong><small>{{ departmentText(scope.row.afterDepartmentName, scope.row.afterDepartmentId) }} · {{ positionText(scope.row.afterPositionName, scope.row.afterPositionId) }}</small></div></template></el-table-column><el-table-column label="来源与操作人" min-width="180"><template #default="scope"><div class="history-value"><strong>{{ scope.row.requestNo || '系统变更' }}</strong><small>{{ scope.row.operatorName || '系统任务' }}</small></div></template></el-table-column></el-table><div v-if="history.total > history.pageSize" class="table-footer"><span>第 {{ history.page }} 页</span><el-pagination v-model:current-page="history.page" v-model:page-size="history.pageSize" layout="prev, pager, next" :total="history.total" @current-change="loadHistory" /></div></section>
  <section class="archive-grid" v-loading="loading"><article v-for="doc in documents.items" :key="doc.id" class="surface-panel document-panel"><div class="document-title"><div class="doc-icon">▤</div><div><span class="section-kicker">{{ doc.documentType }}</span><h2>{{ doc.title }}</h2></div><el-tag effect="plain">{{ (versions[doc.id] || []).length }} 个版本</el-tag></div><div class="version-list"><div v-for="version in versions[doc.id] || []" :key="version.id" class="version-row"><div><strong>V{{ version.versionNo }} · {{ version.originalName }}</strong><small>{{ new Date(version.createdAt).toLocaleString('zh-CN') }} · {{ Math.round(version.size / 1024) }} KB</small></div><el-tag v-if="version.isCurrent" type="success" effect="plain">当前</el-tag><div class="version-actions"><el-button v-if="canMaintainVersion(version)" link title="下载原图" @click="download(version)"><el-icon><Download /></el-icon></el-button><el-button v-else-if="!canManage" link type="primary" title="申请档案访问" @click="requestAccess(version)"><el-icon><Lock /></el-icon>申请访问</el-button><el-button v-if="canMaintainVersion(version)" link type="primary" title="触发 OCR" @click="triggerOcr(version)"><el-icon><Cpu /></el-icon>识别</el-button><el-button v-else-if="!canManage && ocrAvailableIds.includes(version.id)" link type="primary" title="查看 OCR 结果" @click="router.push(`/ocr/${version.id}`)"><el-icon><View /></el-icon>查看识别</el-button></div></div><el-empty v-if="!(versions[doc.id] || []).length" description="暂无版本" :image-size="60" /></div></article><el-empty v-if="!documents.items.length && !loading" class="empty-panel" description="还没有归档材料，请上传第一份脱敏图片" :image-size="90" /></section>
</template>
